assert len(WSKAZNIKI) == 25, f"Bank MOWA ma mieć 25 wskaźników, ma {len(WSKAZNIKI)}"
assert len({w["nr"] for w in WSKAZNIKI}) == 25, "numery wskaźników muszą być unikalne"
assert [w["nr_w_karcie"] for w in WSKAZNIKI] == list(range(1, 26)), \
    "kolejność musi odpowiadać pozycjom 1–25 karty obserwacji"


